"""Publish honest local lab receipt after the finite validation jobs finish."""
from pathlib import Path
import json, subprocess, hashlib, shutil, time
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'local/output'
validation=json.loads((ROOT/'evidence/export_validation.json').read_text(encoding='utf-8'))
assert validation['status']=='PASS'
probe=json.loads((ROOT/'evidence/comfy_cpu_probe.json').read_text(encoding='utf-8'))
assert probe['status']=='CPU_CORE_API_PASS' and probe['owned_probe_process_stopped']
mp4=OUT/'greeting_wave__proxy_previs.mp4'
media=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_entries','stream=codec_name,width,height,r_frame_rate,nb_frames','-show_entries','format=duration,size','-of','json',str(mp4)],text=True))
